package com.hbm.machine.ammopress;
import com.google.gson.*;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.HolderLookup;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Original hbmAmmoPress.json full-list replacement, nullable nine-cell grammar and ordered native synchronization. */
public final class AmmoPressRecipes {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();
 public static void register(){try(var stream=AmmoPressRecipes.class.getResourceAsStream("/hbm/ammo-press-item-aliases.json")){if(stream==null)throw new IllegalStateException("Missing original ammo press aliases");JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(java.io.IOException e){throw new IllegalStateException(e);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent event)->install(event.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent event)->{var server=event.getPlayerList().getServer();if(event.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<AmmoPressRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(AmmoPressContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
 private static AmmoPressRecipe read(JsonObject row,HolderLookup.Provider lookup,int order){var raw=row.getAsJsonArray("input");if(raw.size()!=9)throw new IllegalArgumentException("Source ammo press input must have exactly nine cells");var ingredients=new ArrayList<GenericIngredient>();var cells=new ArrayList<Integer>();for(var value:raw){if(value.isJsonNull())cells.add(-1);else{cells.add(ingredients.size());ingredients.add(GenericRecipeConfigCodec.readIngredient(value.getAsJsonArray(),ALIASES));}}var output=GenericRecipeConfigCodec.readStack(row.getAsJsonArray("output"),ALIASES);return new AmmoPressRecipe(new GenericRecipeData("ammo_press."+order,0,0,ingredients,List.of(),List.of(new GenericOutput(output)),List.of(),List.of(),"",output.copy(),false,"",order),cells);}
 private static void bindDefaultFluidNames(JsonObject root){if(!root.has("dynamicFluidInputs"))return;for(var value:root.getAsJsonArray("dynamicFluidInputs")){var spec=value.getAsJsonObject();var type=com.hbm.fluid.HbmFluids.fromName(spec.get("fluid").getAsString());var key=type.getDict(spec.get("amount").getAsInt(),com.hbm.fluid.FluidContainerConfig.CONTAINER_COMPAT.get());root.getAsJsonArray("recipes").get(spec.get("recipe").getAsInt()).getAsJsonObject().getAsJsonArray("input").get(spec.get("slot").getAsInt()).getAsJsonArray().set(1,new JsonPrimitive(key));}root.remove("dynamicFluidInputs");}
    public static void reload(MinecraftServer server) { install(server); }
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();Path directory=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=directory.resolve("hbmAmmoPress.json");try{Files.createDirectories(directory);JsonObject root;if(Files.isRegularFile(active)){merged.values().removeIf(holder->holder.value().getType()==AmmoPressContent.TYPE.get());try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}}else{try(var stream=AmmoPressRecipes.class.getResourceAsStream("/hbm/ammo-press-source-recipes.json")){if(stream==null)throw new IllegalStateException("Missing true ammo press defaults");root=JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}bindDefaultFluidNames(root);Files.writeString(directory.resolve("_hbmAmmoPress.json"),new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}int order=0;for(var value:root.getAsJsonArray("recipes")){try{var recipe=read(value.getAsJsonObject(),server.registryAccess(),order);var id=AmmoPressContent.id("ammo_press/"+(Files.isRegularFile(active)?"config/":"default/")+order);additions.put(id,new RecipeHolder<>(id,recipe));}catch(Exception e){LogUtils.getLogger().warn("Unbound source ammo press row {}: {}",order,e.getMessage());}order++;}}catch(Exception e){LogUtils.getLogger().error("Cannot load source ammo press recipes",e);}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);}
 private AmmoPressRecipes(){}
}
